insert into hub.app_users (email, display_name, role) values ('mayank.srivastava@mresult.com', 'Mayank Srivastava', 'admin');
insert into hub.consent_versions (version, notice_text, marketing_text) values (1, 'I agree that MResult Technologies may store the details I have entered and use them to follow up with me after the Global Pharma Partnering Summit 2026. My first name or a nickname I choose may be shown on the Pharma Ninja game leaderboard at the MResult booth. The MResult booth team can view this record. I can ask MResult to delete my details at any time.', 'MResult may also send me occasional news and updates about its services. I can unsubscribe at any time.');
insert into hub.settings (id, badge_pattern, badge_hint, consent_version, podcast_topics, demos)
insert into hub.domains (id, name, description, icon_key, accent, enabled, sort_order) values
  ('clinical', 'Clinical Trials', 'Protocols, phases, patients and sites', 'clipboard', '#F7943E', true, 10),
  ('quality', 'Quality & Compliance', 'GxP, audits, CAPA and data integrity', 'shield', '#5EC2B0', true, 20),
  ('mfg', 'Manufacturing & Supply', 'Batches, plants and the cold chain', 'factory', '#E9C46A', true, 30),
  ('rnd', 'R&D & Lab Science', 'Discovery, assays and the lab bench', 'flask', '#9AD27A', true, 40),
  ('genai', 'GenAI & Agents', 'LLMs, agents and AI in pharma', 'chip', '#B794F6', true, 50),
  ('data', 'Data & Cloud', 'Pipelines, platforms and analytics', 'cloud', '#6FA8F5', true, 60),
  ('business', 'Pharma Business', 'Launches, markets and commercial', 'chart', '#F29BC0', true, 70),
  ('india', 'India & Global Pharma', 'Regulators, generics and world markets', 'globe', '#F2857A', true, 80);
insert into hub.questions (id, domain_id, question_text, options, correct_index, difficulty, explanation, source, enabled) values
  ('ct-01', 'clinical', 'ICH E6(R3), the revised Good Clinical Practice guideline, became effective in the EU on which date?', array['1 January 2024', '31 January 2025', '23 July 2025', '1 January 2026']::text[], 2, 3, 'ICH adopted E6(R3) in January 2025, and the EMA set 23 July 2025 as the date it took effect in the EU.', 'TEST - Darshan prototype', true),
  ('ct-02', 'clinical', 'By when did trials under the old EU Clinical Trials Directive have to move to the Clinical Trials Regulation (CTR)?', array['31 January 2023', '31 January 2025', '30 June 2025', '31 December 2026']::text[], 1, 3, 'The CTR’s three-year transition period ended on 31 January 2025. Any ongoing trial authorised under Directive 2001/20/EC had to be transitioned by then.', 'TEST - Darshan prototype', true),
  ('ct-03', 'clinical', 'What is the single EU portal and database used to submit and manage clinical trial applications under the CTR?', array['EudraVigilance', 'CTIS', 'EudraCT', 'IRIS']::text[], 1, 1, 'The Clinical Trials Information System (CTIS) is the single entry point for sponsors and regulators under the CTR. EudraCT served the old Directive.', 'TEST - Darshan prototype', true),
  ('ct-04', 'clinical', 'In September 2024, the FDA finalised guidance on which topic?', array['Decentralized trial elements', 'Placebo in oncology trials', 'Electronic informed consent', 'Single IRB review']::text[], 0, 2, 'FDA’s final guidance “Conducting Clinical Trials With Decentralized Elements” covers remote visits, local healthcare providers, direct-to-patient shipping of investigational products, and related oversight.', 'TEST - Darshan prototype', true),
  ('ct-05', 'clinical', 'ICH E6(R3) is organised as overarching principles plus annexes. What does Annex 2 address?', array['Investigator’s Brochure', 'Essential records retention', 'Non-traditional designs', 'Pharmacovigilance timelines']::text[], 2, 3, 'Annex 1 covers traditional interventional trials. Annex 2 adds considerations for decentralized elements, pragmatic designs and the use of real-world data sources.', 'TEST - Darshan prototype', true),
  ('ct-06', 'clinical', 'ICH E6(R3) asks sponsors to build quality in from the start by identifying which of the following?', array['Critical to quality factors', 'Key opinion leaders', 'Maximum tolerated doses', 'Site payment milestones']::text[], 0, 1, 'E6(R3) leans on quality by design: identify the factors critical to trial quality, then apply risk-proportionate controls to them rather than monitoring everything equally.', 'TEST - Darshan prototype', true),
  ('ct-07', 'clinical', 'Under the US FDORA law of 2022, sponsors of which studies must submit Diversity Action Plans?', array['All Phase 1 studies', 'Phase 3/pivotal studies', 'Only non-US studies', 'Only rare-disease studies']::text[], 1, 2, 'FDORA requires Diversity Action Plans for Phase 3 or other pivotal drug and biologic studies and for many device studies, setting enrolment goals by demographic group. FDA issued draft guidance in June 2024.', 'TEST - Darshan prototype', true),
  ('ct-08', 'clinical', 'In January 2025, the FDA issued draft guidance on AI to support drug and biologic decisions. What does it propose?', array['Ban on AI-generated data', 'Risk-based credibility', 'Mandatory open-source models', 'CDER pre-approves all AI']::text[], 1, 2, 'The draft guidance lays out a risk-based, multi-step framework for establishing the credibility of an AI model for its specific context of use.', 'TEST - Darshan prototype', true),
  ('ct-09', 'clinical', 'In June 2025, the FDA rolled out an agency-wide generative AI tool for staff, including reviewers. What is it called?', array['Elsa', 'Sentinel', 'Atlas', 'Iris']::text[], 0, 1, 'FDA launched Elsa in June 2025 to help staff with tasks such as summarising information and speeding up reviews. Sentinel is FDA’s long-running safety surveillance system.', 'TEST - Darshan prototype', true),
  ('ct-10', 'clinical', 'Which country’s overhauled clinical trial regulations, signed into law in 2025, came into force in April 2026?', array['Australia', 'Canada', 'United Kingdom', 'Japan']::text[], 2, 1, 'The UK’s updated clinical trials regulations, overseen by the MHRA, came into force in April 2026 after a 12-month implementation period, aiming for faster, more proportionate approvals.', 'TEST - Darshan prototype', true),
  ('qc-01', 'quality', 'What does GMP stand for?', array['Good Manufacturing Practice', 'General Medical Protocol', 'Global Marketing Plan', 'Good Monitoring Process']::text[], 0, 1, 'GMP is the system that ensures medicines are consistently produced and controlled to quality standards.', 'TEST - seed', true),
  ('qc-02', 'quality', 'ALCOA principles mainly protect what?', array['Patient privacy', 'Data integrity', 'Drug pricing', 'Supply security', 'Lab safety']::text[], 1, 1, 'Attributable, Legible, Contemporaneous, Original, Accurate: the basis of trustworthy GxP records.', 'TEST - seed', true),
  ('qc-03', 'quality', 'Which FDA rule covers electronic records and electronic signatures?', array['21 CFR Part 211', 'ICH Q10', '21 CFR Part 11', 'ISO 13485']::text[], 2, 2, 'Part 11 sets FDA criteria for electronic records and signatures; Part 211 covers GMP for finished pharmaceuticals.', 'TEST - seed', true),
  ('qc-04', 'quality', 'In CAPA, what does the “P” stand for?', array['Procedural', 'Primary', 'Preventive', 'Product', 'Planned']::text[], 2, 2, 'Corrective and Preventive Action: fix the cause of a problem and stop it happening again.', 'TEST - seed', true),
  ('qc-05', 'quality', 'Which ICH guideline covers quality risk management?', array['ICH Q1A', 'ICH Q9', 'ICH E6', 'ICH M7']::text[], 1, 3, 'ICH Q9 sets out principles and tools for quality risk management across the product lifecycle.', 'TEST - seed', true),
  ('ms-01', 'mfg', 'Most refrigerated “cold chain” medicines must be kept in which range?', array['2 to 8 °C', '−5 to 0 °C', '10 to 15 °C', '20 to 25 °C']::text[], 0, 1, 'Most refrigerated medicines must stay between 2 °C and 8 °C from plant to patient.', 'TEST - seed', true),
  ('ms-02', 'mfg', 'In drug manufacturing, API stands for Active Pharmaceutical what?', array['Inhibitor', 'Ingredient', 'Indicator', 'Isolate']::text[], 1, 1, 'The API is the component that produces the medicine’s intended effect; excipients make up the rest of the dose form.', 'TEST - seed', true),
  ('ms-03', 'mfg', 'What is the main purpose of a pharmaceutical cleanroom?', array['Speed up packaging', 'Store finished goods', 'Control airborne particles', 'Reduce energy use', 'Train new operators']::text[], 2, 2, 'Cleanrooms are classified by how many airborne particles they allow, protecting sterile and sensitive products.', 'TEST - seed', true),
  ('ms-04', 'mfg', 'Lyophilisation is better known as what?', array['Sterile filtration', 'Freeze-drying', 'Wet granulation', 'Tablet coating']::text[], 1, 2, 'Lyophilisation removes water by freezing a product and then sublimating the ice under vacuum, which helps preserve biologics.', 'TEST - seed', true),
  ('ms-05', 'mfg', 'Under the EU Falsified Medicines Directive, packs need a unique identifier and what else?', array['RFID tag', 'Hologram sticker', 'Anti-tamper device', 'Batch photograph', 'Pharmacist signature']::text[], 2, 3, 'Since February 2019, most EU prescription packs carry a unique identifier in a 2D code plus an anti-tampering device.', 'TEST - seed', true),
  ('rd-01', 'rnd', 'What does PCR stand for?', array['Protein cell response', 'Polymerase chain reaction', 'Primary culture ratio', 'Peptide chain reading']::text[], 1, 1, 'PCR copies a target DNA sequence millions of times, making tiny samples measurable.', 'TEST - seed', true),
  ('rd-02', 'rnd', 'Which molecule carries the genetic instructions in most living things?', array['ATP', 'Insulin', 'DNA', 'Collagen', 'Glucose']::text[], 2, 1, 'DNA stores the genetic instructions used to build and run cells; RNA carries copies of them to make proteins.', 'TEST - seed', true),
  ('rd-03', 'rnd', 'Monoclonal antibodies are made by copies of what?', array['A single parent cell', 'Many donor cells', 'A bacterial virus', 'A synthetic peptide']::text[], 0, 2, 'Monoclonal antibodies come from clones of one immune cell, so they all bind the same target.', 'TEST - seed', true),
  ('rd-04', 'rnd', 'What does CRISPR-Cas9 mainly do?', array['Sequences proteins', 'Edits DNA sequences', 'Measures blood sugar', 'Stains tissue slides', 'Purifies antibodies']::text[], 1, 2, 'Cas9, guided by an RNA sequence, cuts DNA at a chosen spot so genes can be changed, removed or added.', 'TEST - seed', true),
  ('rd-05', 'rnd', 'In drug discovery, what does an IC50 value describe?', array['Peak blood level', 'Elimination half-life', 'Half-maximal inhibition', 'Lethal dose']::text[], 2, 3, 'IC50 is the concentration of a compound needed to inhibit a biological process by half; lower means more potent.', 'TEST - seed', true),
  ('ai-01', 'genai', 'What does LLM stand for?', array['Large language model', 'Linked logic machine', 'Low latency memory', 'Learned label method']::text[], 0, 1, 'A large language model is a neural network trained on large amounts of text to predict and generate language.', 'TEST - seed', true),
  ('ai-02', 'genai', 'What is an AI “hallucination”?', array['A visual glitch', 'Confident but false output', 'A hardware fault', 'A training pause', 'A user error']::text[], 1, 1, 'A hallucination is output that sounds plausible but is wrong or made up, which is why AI answers need checking against sources.', 'TEST - seed', true),
  ('ai-03', 'genai', 'In RAG, what does the “R” stand for?', array['Reasoning', 'Regression', 'Retrieval', 'Ranking']::text[], 2, 2, 'Retrieval-augmented generation fetches relevant documents first, then lets the model answer from them, which grounds its output.', 'TEST - seed', true),
  ('ai-04', 'genai', 'What makes an AI system an “agent” rather than a chatbot?', array['It has an avatar', 'It acts using tools', 'It runs offline', 'It uses more data']::text[], 1, 2, 'An AI agent plans steps and uses tools such as search, code or business systems to act towards a goal, not just reply.', 'TEST - seed', true),
  ('ai-05', 'genai', 'What is a “token” to a large language model?', array['A login password', 'A GPU time unit', 'A chunk of text', 'A training label', 'A model version']::text[], 2, 3, 'Models read and write text as tokens, pieces of words or characters; context limits and costs are counted in tokens.', 'TEST - seed', true),
  ('dc-01', 'data', 'What does SaaS stand for?', array['Storage and Sync', 'Software as a Service', 'Secure Access Server', 'System as a Solution']::text[], 1, 1, 'Software as a Service is software delivered over the internet on subscription instead of installed locally.', 'TEST - seed', true),
  ('dc-02', 'data', 'Which of these is a query language for relational databases?', array['HTML', 'CSS', 'SQL', 'JSON', 'YAML']::text[], 2, 1, 'SQL (Structured Query Language) is used to define, read and update data in relational databases.', 'TEST - seed', true),
  ('dc-03', 'data', 'What does ETL stand for in data engineering?', array['Encrypt, test, launch', 'Extract, transform, load', 'Edit, track, log', 'Export, tag, label']::text[], 1, 2, 'ETL pipelines extract data from sources, transform it into a usable shape and load it into a target such as a warehouse.', 'TEST - seed', true),
  ('dc-04', 'data', 'What is a “data lake”?', array['A backup tape library', 'A cooling system', 'Store of raw data', 'A data privacy law']::text[], 2, 2, 'A data lake stores large volumes of raw data in its original formats, ready for later analysis.', 'TEST - seed', true),
  ('dc-05', 'data', 'In the FAIR data principles, what does the “I” stand for?', array['Indexed', 'Interoperable', 'Integrated', 'Immutable', 'Identified']::text[], 1, 3, 'FAIR data is Findable, Accessible, Interoperable and Reusable, a framework widely adopted in life sciences.', 'TEST - seed', true),
  ('pb-01', 'business', 'What is a generic medicine?', array['An unbranded vitamin', 'Off-patent equivalent drug', 'An experimental drug', 'A herbal remedy']::text[], 1, 1, 'A generic contains the same active ingredient as an original brand and is sold once patents and exclusivity expire.', 'TEST - seed', true),
  ('pb-02', 'business', 'What does OTC mean on a medicine?', array['Only to clinicians', 'Over the counter', 'Oral tablet coating', 'Ordered through chemist']::text[], 1, 1, 'Over-the-counter medicines can be bought without a prescription.', 'TEST - seed', true),
  ('pb-03', 'business', 'What is a “biosimilar”?', array['A copied small molecule', 'A plant-based drug', 'Near-copy of a biologic', 'A combination vaccine', 'A rebranded generic']::text[], 2, 2, 'A biosimilar is highly similar to an approved biologic medicine, with no meaningful differences in safety or efficacy.', 'TEST - seed', true),
  ('pb-04', 'business', 'What is a “patent cliff”?', array['A failed trial result', 'Revenue drop after expiry', 'A price control law', 'A merger deadline']::text[], 1, 2, 'When key patents expire, generic or biosimilar rivals arrive and the originator’s sales can fall sharply.', 'TEST - seed', true),
  ('pb-05', 'business', 'In HEOR, what does the “E” stand for?', array['Evidence', 'Efficacy', 'Economics', 'Epidemiology', 'Ethics']::text[], 2, 3, 'HEOR is health economics and outcomes research: evidence on value, cost and real-world outcomes for payers.', 'TEST - seed', true),
  ('ig-01', 'india', 'Which body is India’s national drug regulator?', array['FSSAI', 'CDSCO', 'ICMR', 'NITI Aayog']::text[], 1, 1, 'The Central Drugs Standard Control Organisation, headed by the DCGI, regulates drug approvals and clinical trials in India.', 'TEST - seed', true),
  ('ig-02', 'india', 'India is often called the “pharmacy of the world” for supplying what?', array['Rare-earth metals', 'Medical robots', 'Affordable generics', 'Patent licences', 'Herbal teas']::text[], 2, 1, 'India is one of the largest suppliers of generic medicines by volume, serving markets across the world.', 'TEST - seed', true),
  ('ig-03', 'india', 'WHO prequalification helps UN agencies buy what?', array['Hospital buildings', 'Quality-assured medicines', 'Medical insurance', 'Lab equipment']::text[], 1, 2, 'WHO prequalification checks that medicines and vaccines meet global quality, safety and efficacy standards for procurement by UN agencies.', 'TEST - seed', true),
  ('ig-04', 'india', 'In India, what is Schedule M of the Drugs and Cosmetics Rules about?', array['Drug pricing caps', 'Clinical trial fees', 'Good Manufacturing Practice', 'Import duties', 'Pharmacy licences']::text[], 2, 2, 'Schedule M sets the GMP requirements for manufacturers in India; a revised version brought it closer to global standards.', 'TEST - seed', true),
  ('ig-05', 'india', 'Which body harmonises drug rules across regulators such as FDA, EMA and Japan’s PMDA?', array['WTO', 'OECD', 'ICH', 'UNESCO']::text[], 2, 3, 'The International Council for Harmonisation brings regulators and industry together to write shared technical guidelines.', 'TEST - seed', true);
